package com.musiccatalog.controller; import com.musiccatalog.dto.AlbumDtos.*; import com.musiccatalog.service.LibraryService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/library") public class LibraryController {private final LibraryService s;public LibraryController(LibraryService s){this.s=s;} @GetMapping public List<LibraryAlbum> all(Authentication a){return s.all(a.getName());} @PostMapping public ResponseEntity<LibraryAlbum> add(Authentication a,@Valid @RequestBody AddAlbum d){return ResponseEntity.status(HttpStatus.CREATED).body(s.add(a.getName(),d));} @PutMapping("/{id}") public LibraryAlbum update(Authentication a,@PathVariable Long id,@Valid @RequestBody UpdateAlbum d){return s.update(a.getName(),id,d);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(Authentication a,@PathVariable Long id){s.delete(a.getName(),id);} }
